/** Image that degrades to a labeled placeholder if the file isn't there yet. */
function Img({
  file,
  alt,
  ratio = '16/9',
  label,
  className = '',
  rounded = true,
}: {
  file: string;
  alt: string;
  ratio?: string;
  label?: string;
  className?: string;
  rounded?: boolean;
}) {
  const [ok, setOk] = useState(true);
  if (ok) {
    return (
      <img
        src={`${ASSET}images/hume/ana/${file}`}
        alt={alt}
        onError={() => setOk(false)}
        loading="lazy"
        className={className}
      />
    );
  }
  return (
    <div
      style={{ aspectRatio: ratio }}
      className={`flex w-full flex-col items-center justify-center gap-1 border border-dashed border-[#CBD5DD] bg-[#EEF3F6] p-4 text-center ${
        rounded ? 'rounded-none' : ''
      }`}
    >
      <span className="text-[11px] font-semibold uppercase tracking-wider text-[#93A2AE] font-['Open_Sans']">
        Image · {ratio}
      </span>
      {label && <span className="max-w-md text-sm text-[#5E6E7A] font-['Open_Sans']">{label}</span>}
      <span className="text-[11px] text-[#AAB6C0] font-['Open_Sans']">/images/hume/ana/{file}</span>
    </div>
  );
}

